DECLARE payload jsonb := $data$[{"language":"es","slug":"casuela-de-mariscos","public_path":"/casuela-de-mariscos","title":"Cazuela de mariscos colombiana con leche de coco","excerpt":"Una cazuela inspirada en la cocina de la costa Caribe colombiana, con pescado, camarones y calamar en un caldo de coco y sofrito criollo. Sirve caliente con arroz y patacón.","summary":"Una cazuela inspirada en la cocina de la costa Caribe colombiana, con pescado, camarones y calamar en un caldo de coco y sofrito criollo. Sirve caliente con arroz y patacón.","ingredients":[{"amount":"400","unit":"g","name":"filete de pescado blanco firme, sin piel ni espinas, en cubos"},{"amount":"300","unit":"g","name":"camarones crudos pelados y limpios"},{"amount":"250","unit":"g","name":"calamar limpio en aros y tentáculos"},{"amount":"400","unit":"ml","name":"leche de coco sin azúcar"},{"amount":"300","unit":"ml","name":"agua"},{"amount":"120","unit":"g","name":"cebolla blanca picada"},{"amount":"100","unit":"g","name":"pimentón rojo picado"},{"amount":"200","unit":"g","name":"tomate maduro picado"},{"amount":"9","unit":"g","name":"ajo picado"},{"amount":"15","unit":"g","name":"aceite de oliva"},{"amount":"4","unit":"g","name":"sal"},{"amount":"5","unit":"g","name":"cilantro fresco picado, opcional para servir"}],"steps":[{"title":"Pica los vegetales","content":"Pica finamente la cebolla, el pimentón, el ajo y los tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pica los vegetales"},{"title":"Sofríe los aromáticos","content":"Cocina la cebolla, el pimentón y el ajo con el aceite en una olla a fuego medio durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sofríe los aromáticos"},{"title":"Cocina el tomate","content":"Agrega el tomate y cocina 6 minutos, hasta formar un sofrito suave.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cocina el tomate"},{"title":"Prepara el caldo","content":"Añade el agua, la leche de coco y la sal; cocina a fuego suave durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepara el caldo"},{"title":"Cocina el calamar","content":"Incorpora el calamar y mantén un hervor suave durante 15 minutos; si aún está firme, prolonga la cocción hasta que quede tierno antes de añadir el pescado.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cocina el calamar"},{"title":"Añade el pescado","content":"Agrega el pescado en cubos y cocina suavemente durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Añade el pescado"},{"title":"Cocina el camarón","content":"Añade los camarones y cocina durante 3–4 minutos, hasta que estén rosados y opacos; verifica que el pescado esté cocido y el calamar tierno.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cocina el camarón"},{"title":"Sirve la cazuela","content":"Sirve la cazuela caliente con el cilantro opcional. Acompaña con arroz blanco y patacón si lo deseas.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirve la cazuela"}],"seo":{"title":"Cazuela de mariscos colombiana con leche de coco","description":"Prepara cazuela de mariscos costeña con pescado, camarones y calamar en caldo de coco y sofrito. Ingredientes, pasos y consejos.","image_alt":"Cazuela de mariscos colombiana con leche de coco","faq":[{"q":"¿Puedo usar mariscos congelados?","a":"Sí. Descongélalos en la nevera y pésalos limpios antes de comenzar."},{"q":"¿Por qué se endurece el calamar?","a":"La cocción insuficiente o prolongada sin líquido puede dejarlo firme. Mantén el hervor suave y continúa unos minutos si aún está duro."},{"q":"¿Puedo preparar el sofrito con anticipación?","a":"Sí. Refrigéralo en recipiente cerrado y caliéntalo antes de agregar el caldo y cocinar los mariscos."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"1 de 4 porciones, sin acompañamientos","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Estimación sin cilantro opcional ni acompañamientos; la composición de la leche de coco y los mariscos puede variar. El agua no aporta nutrientes."},"notes":"<p>Usa pescado y mariscos refrigerados; descongela en la nevera antes de empezar. Evita hervir fuerte para conservar la textura del pescado. Cocina el pescado hasta 63 °C en el centro; camarones y calamar deben verse opacos y firmes. Contiene pescado, crustáceos y moluscos. Acompañamientos no incluidos en el cálculo nutricional.</p>","category":"Platos principales","cuisine":"Colombiana","difficulty":"Fácil","course":"Plato principal","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Cazuela de mariscos colombiana con leche de coco"],"content_html":""},{"language":"de","slug":"kolumbianischer-meeresfruechte-eintopf-mit-kokosmilch","public_path":"/de/kolumbianischer-meeresfruechte-eintopf-mit-kokosmilch","title":"Kolumbianischer Meeresfrüchte-Eintopf mit Kokosmilch","excerpt":"Ein Eintopf der kolumbianischen Karibikküste mit Fisch, Garnelen und Tintenfisch in Kokos-Tomaten-Brühe.","summary":"Ein Eintopf der kolumbianischen Karibikküste mit Fisch, Garnelen und Tintenfisch in Kokos-Tomaten-Brühe.","ingredients":[{"amount":"400","unit":"g","name":"festes weißes Fischfilet ohne Haut und Gräten, gewürfelt"},{"amount":"300","unit":"g","name":"rohe Garnelen, geschält und geputzt"},{"amount":"250","unit":"g","name":"geputzter Tintenfisch in Ringen und Tentakeln"},{"amount":"400","unit":"ml","name":"ungesüßte Kokosmilch"},{"amount":"300","unit":"ml","name":"Wasser"},{"amount":"120","unit":"g","name":"weiße Zwiebel, gehackt"},{"amount":"100","unit":"g","name":"rote Paprika, gehackt"},{"amount":"200","unit":"g","name":"reife Tomaten, gehackt"},{"amount":"9","unit":"g","name":"Knoblauch, gehackt"},{"amount":"15","unit":"g","name":"Olivenöl"},{"amount":"4","unit":"g","name":"Salz"},{"amount":"5","unit":"g","name":"frischer Koriander, gehackt, optional"}],"steps":[{"title":"Gemüse schneiden","content":"Zwiebel, Paprika, Knoblauch und Tomaten fein schneiden.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Gemüse schneiden"},{"title":"Aromaten anschwitzen","content":"Zwiebel, Paprika und Knoblauch im Öl bei mittlerer Hitze 5 Minuten garen.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Aromaten anschwitzen"},{"title":"Tomaten garen","content":"Tomaten zugeben und 6 Minuten weich garen.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Tomaten garen"},{"title":"Brühe zubereiten","content":"Wasser, Kokosmilch und Salz zugeben und 5 Minuten sanft köcheln.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Brühe zubereiten"},{"title":"Tintenfisch garen","content":"Tintenfisch 15 Minuten sanft köcheln lassen; falls er noch fest ist, vor Zugabe des Fischs weitergaren, bis er zart ist.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Tintenfisch garen"},{"title":"Fisch zugeben","content":"Fischwürfel zugeben und 5 Minuten sanft garen.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Fisch zugeben"},{"title":"Garnelen garen","content":"Garnelen zugeben und 3–4 Minuten garen, bis sie rosa und undurchsichtig sind. Fisch und Tintenfisch prüfen.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Garnelen garen"},{"title":"Eintopf servieren","content":"Heiß mit optionalem Koriander servieren. Nach Wunsch weißen Reis und Patacón dazu reichen.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Eintopf servieren"}],"seo":{"title":"Kolumbianischer Meeresfrüchte-Eintopf mit Kokosmilch","description":"Ein Eintopf der kolumbianischen Karibikküste mit Fisch, Garnelen und Tintenfisch in Kokos-Tomaten-Brühe.","image_alt":"Kolumbianischer Meeresfrüchte-Eintopf mit Kokosmilch","faq":[{"q":"Kann ich Tiefkühl-Meeresfrüchte verwenden?","a":"Ja. Im Kühlschrank auftauen und geputzt wiegen."},{"q":"Warum ist der Tintenfisch fest?","a":"Sanft köcheln und bei Bedarf einige Minuten länger garen."},{"q":"Kann ich den Sofrito vorbereiten?","a":"Ja. Abgedeckt kühlen und vor Zugabe von Brühe und Meeresfrüchten erhitzen."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"Ein Viertel des Rezepts, ohne Beilagen","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Schätzung ohne optionalen Koriander und Beilagen. Die Werte hängen von den Produkten ab."},"notes":"<p>Meeresfrüchte im Kühlschrank auftauen und sanft garen. Fisch im Kern auf 63 °C erhitzen; Garnelen und Tintenfisch sollen undurchsichtig und fest sein. Enthält Fisch, Krebstiere und Weichtiere.</p>","category":"Hauptgerichte","cuisine":"Kolumbianisch","difficulty":"Einfach","course":"Hauptgericht","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Kolumbianischer Meeresfrüchte-Eintopf mit Kokosmilch"],"content_html":""},{"language":"en","slug":"colombian-coconut-seafood-stew","public_path":"/en/colombian-coconut-seafood-stew","title":"Colombian seafood stew with coconut milk","excerpt":"A Caribbean Colombian seafood stew with fish, shrimp and squid in a coconut and tomato sofrito broth.","summary":"A Caribbean Colombian seafood stew with fish, shrimp and squid in a coconut and tomato sofrito broth.","ingredients":[{"amount":"400","unit":"g","name":"firm white fish fillet, skinless and boneless, cubed"},{"amount":"300","unit":"g","name":"raw shrimp, peeled and cleaned"},{"amount":"250","unit":"g","name":"cleaned squid rings and tentacles"},{"amount":"400","unit":"ml","name":"unsweetened coconut milk"},{"amount":"300","unit":"ml","name":"water"},{"amount":"120","unit":"g","name":"white onion, chopped"},{"amount":"100","unit":"g","name":"red bell pepper, chopped"},{"amount":"200","unit":"g","name":"ripe tomatoes, chopped"},{"amount":"9","unit":"g","name":"garlic, chopped"},{"amount":"15","unit":"g","name":"olive oil"},{"amount":"4","unit":"g","name":"salt"},{"amount":"5","unit":"g","name":"fresh cilantro, chopped, optional"}],"steps":[{"title":"Chop the vegetables","content":"Finely chop the onion, pepper, garlic and tomatoes.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Chop the vegetables"},{"title":"Sauté the aromatics","content":"Cook the onion, pepper and garlic in oil over medium heat for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sauté the aromatics"},{"title":"Cook the tomato","content":"Add the tomato and cook for 6 minutes until soft.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cook the tomato"},{"title":"Make the broth","content":"Add the water, coconut milk and salt; simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Make the broth"},{"title":"Cook the squid","content":"Add the squid and simmer gently for 15 minutes; if still firm, continue until tender before adding the fish.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cook the squid"},{"title":"Add the fish","content":"Add the fish cubes and simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Add the fish"},{"title":"Cook the shrimp","content":"Add the shrimp and cook for 3–4 minutes until pink and opaque. Check the fish is cooked and the squid tender.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cook the shrimp"},{"title":"Serve the stew","content":"Serve hot with optional cilantro. Add white rice and patacón if desired.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Serve the stew"}],"seo":{"title":"Colombian seafood stew with coconut milk","description":"A Caribbean Colombian seafood stew with fish, shrimp and squid in a coconut and tomato sofrito broth.","image_alt":"Colombian seafood stew with coconut milk","faq":[{"q":"Can I use frozen seafood?","a":"Yes. Thaw in the refrigerator and weigh after cleaning."},{"q":"Why is the squid tough?","a":"Simmer gently and continue cooking for a few minutes if it is still firm."},{"q":"Can I make the sofrito ahead?","a":"Yes. Refrigerate it in a closed container and heat before adding the broth and seafood."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"One quarter of the stew, without sides","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Estimated without optional cilantro or side dishes. Coconut milk and seafood vary by product."},"notes":"<p>Thaw seafood in the refrigerator. Keep the simmer gentle. Cook fish to 63 °C; shrimp and squid should be opaque and firm. Contains fish, crustaceans and mollusks. Sides are excluded from nutrition.</p>","category":"Main dishes","cuisine":"Colombian","difficulty":"Easy","course":"Main course","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Colombian seafood stew with coconut milk"],"content_html":""},{"language":"fr","slug":"cazuela-colombienne-fruits-de-mer-lait-de-coco","public_path":"/fr/cazuela-colombienne-fruits-de-mer-lait-de-coco","title":"Cazuela colombienne aux fruits de mer et lait de coco","excerpt":"Une cazuela de la côte caraïbe colombienne au poisson, aux crevettes et au calmar, dans un bouillon de coco et de tomate.","summary":"Une cazuela de la côte caraïbe colombienne au poisson, aux crevettes et au calmar, dans un bouillon de coco et de tomate.","ingredients":[{"amount":"400","unit":"g","name":"filet de poisson blanc ferme sans peau ni arêtes, en dés"},{"amount":"300","unit":"g","name":"crevettes crues décortiquées et nettoyées"},{"amount":"250","unit":"g","name":"calmar nettoyé en anneaux et tentacules"},{"amount":"400","unit":"ml","name":"lait de coco sans sucre"},{"amount":"300","unit":"ml","name":"eau"},{"amount":"120","unit":"g","name":"oignon blanc émincé"},{"amount":"100","unit":"g","name":"poivron rouge émincé"},{"amount":"200","unit":"g","name":"tomates mûres émincées"},{"amount":"9","unit":"g","name":"ail haché"},{"amount":"15","unit":"g","name":"huile d’olive"},{"amount":"4","unit":"g","name":"sel"},{"amount":"5","unit":"g","name":"coriandre fraîche hachée, facultative"}],"steps":[{"title":"Hachez les légumes","content":"Hachez finement l’oignon, le poivron, l’ail et les tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Hachez les légumes"},{"title":"Faites revenir les aromates","content":"Faites cuire l’oignon, le poivron et l’ail dans l’huile à feu moyen pendant 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Faites revenir les aromates"},{"title":"Cuisez la tomate","content":"Ajoutez la tomate et laissez cuire 6 minutes jusqu’à ce qu’elle soit tendre.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuisez la tomate"},{"title":"Préparez le bouillon","content":"Ajoutez l’eau, le lait de coco et le sel ; laissez frémir 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Préparez le bouillon"},{"title":"Cuisez le calmar","content":"Ajoutez le calmar et laissez frémir 15 minutes ; s’il est encore ferme, poursuivez jusqu’à ce qu’il soit tendre avant d’ajouter le poisson.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuisez le calmar"},{"title":"Ajoutez le poisson","content":"Ajoutez les dés de poisson et laissez cuire doucement 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Ajoutez le poisson"},{"title":"Cuisez les crevettes","content":"Ajoutez les crevettes et cuisez 3 à 4 minutes jusqu’à ce qu’elles soient roses et opaques. Vérifiez le poisson et le calmar.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuisez les crevettes"},{"title":"Servez la cazuela","content":"Servez chaud avec la coriandre facultative, du riz blanc et un patacón selon vos envies.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servez la cazuela"}],"seo":{"title":"Cazuela colombienne aux fruits de mer et lait de coco","description":"Une cazuela de la côte caraïbe colombienne au poisson, aux crevettes et au calmar, dans un bouillon de coco et de tomate.","image_alt":"Cazuela colombienne aux fruits de mer et lait de coco","faq":[{"q":"Puis-je utiliser des fruits de mer surgelés ?","a":"Oui. Décongelez-les au réfrigérateur et pesez-les une fois nettoyés."},{"q":"Pourquoi le calmar est-il ferme ?","a":"Maintenez un léger frémissement et prolongez la cuisson de quelques minutes si nécessaire."},{"q":"Puis-je préparer le sofrito à l’avance ?","a":"Oui. Gardez-le au réfrigérateur dans un récipient fermé puis réchauffez-le avant d’ajouter le bouillon et les fruits de mer."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"Un quart de la recette, sans accompagnement","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Estimation sans coriandre facultative ni accompagnement. Les produits utilisés font varier les valeurs."},"notes":"<p>Décongelez les fruits de mer au réfrigérateur. Maintenez un léger frémissement. Le poisson doit atteindre 63 °C à cœur ; les crevettes et le calmar doivent être opaques et fermes. Contient poisson, crustacés et mollusques.</p>","category":"Plats principaux","cuisine":"Colombienne","difficulty":"Facile","course":"Plat principal","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Cazuela colombienne aux fruits de mer et lait de coco"],"content_html":""},{"language":"it","slug":"cazuela-colombiana-frutti-di-mare-latte-di-cocco","public_path":"/it/cazuela-colombiana-frutti-di-mare-latte-di-cocco","title":"Cazuela colombiana di frutti di mare al latte di cocco","excerpt":"Una cazuela della costa caraibica colombiana con pesce, gamberi e calamari in brodo di cocco e soffritto al pomodoro.","summary":"Una cazuela della costa caraibica colombiana con pesce, gamberi e calamari in brodo di cocco e soffritto al pomodoro.","ingredients":[{"amount":"400","unit":"g","name":"filetto di pesce bianco sodo senza pelle e lische, a cubetti"},{"amount":"300","unit":"g","name":"gamberi crudi sgusciati e puliti"},{"amount":"250","unit":"g","name":"calamaro pulito ad anelli e tentacoli"},{"amount":"400","unit":"ml","name":"latte di cocco senza zucchero"},{"amount":"300","unit":"ml","name":"acqua"},{"amount":"120","unit":"g","name":"cipolla bianca tritata"},{"amount":"100","unit":"g","name":"peperone rosso tritato"},{"amount":"200","unit":"g","name":"pomodori maturi tritati"},{"amount":"9","unit":"g","name":"aglio tritato"},{"amount":"15","unit":"g","name":"olio d’oliva"},{"amount":"4","unit":"g","name":"sale"},{"amount":"5","unit":"g","name":"coriandolo fresco tritato, facoltativo"}],"steps":[{"title":"Trita le verdure","content":"Trita finemente cipolla, peperone, aglio e pomodori.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Trita le verdure"},{"title":"Soffriggi gli aromi","content":"Cuoci cipolla, peperone e aglio nell’olio a fuoco medio per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Soffriggi gli aromi"},{"title":"Cuoci il pomodoro","content":"Aggiungi il pomodoro e cuoci per 6 minuti, finché morbido.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuoci il pomodoro"},{"title":"Prepara il brodo","content":"Aggiungi acqua, latte di cocco e sale; fai sobbollire per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepara il brodo"},{"title":"Cuoci il calamaro","content":"Aggiungi il calamaro e fai sobbollire per 15 minuti; se è ancora sodo, continua finché tenero prima di aggiungere il pesce.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuoci il calamaro"},{"title":"Aggiungi il pesce","content":"Unisci i cubetti di pesce e cuoci dolcemente per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Aggiungi il pesce"},{"title":"Cuoci i gamberi","content":"Aggiungi i gamberi e cuoci 3–4 minuti finché rosa e opachi. Controlla il pesce e la tenerezza del calamaro.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuoci i gamberi"},{"title":"Servi la cazuela","content":"Servi calda con coriandolo facoltativo e, se vuoi, riso bianco e patacón.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servi la cazuela"}],"seo":{"title":"Cazuela colombiana di frutti di mare al latte di cocco","description":"Una cazuela della costa caraibica colombiana con pesce, gamberi e calamari in brodo di cocco e soffritto al pomodoro.","image_alt":"Cazuela colombiana di frutti di mare al latte di cocco","faq":[{"q":"Posso usare frutti di mare congelati?","a":"Sì. Scongelali in frigorifero e pesali puliti."},{"q":"Perché il calamaro è duro?","a":"Mantieni un leggero bollore e prolunga la cottura di qualche minuto se è ancora sodo."},{"q":"Posso preparare il soffritto prima?","a":"Sì. Conservalo coperto in frigorifero e scaldalo prima di aggiungere brodo e frutti di mare."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"Un quarto della ricetta, senza contorni","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Stima senza coriandolo facoltativo né contorni. I valori variano secondo i prodotti."},"notes":"<p>Scongela i frutti di mare in frigorifero e mantieni il bollore leggero. Il pesce deve raggiungere 63 °C al cuore; gamberi e calamari devono essere opachi e sodi. Contiene pesce, crostacei e molluschi.</p>","category":"Secondi piatti","cuisine":"Colombiana","difficulty":"Facile","course":"Secondo","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Cazuela colombiana di frutti di mare al latte di cocco"],"content_html":""},{"language":"ja","slug":"kolombia-kaisen-kokonattsu-nikomi","public_path":"/ja/kolombia-kaisen-kokonattsu-nikomi","title":"コロンビア風シーフードのココナッツ煮込み","excerpt":"コロンビアのカリブ海沿岸風に、白身魚、えび、いかをココナッツとトマトのスープで煮込みます。","summary":"コロンビアのカリブ海沿岸風に、白身魚、えび、いかをココナッツとトマトのスープで煮込みます。","ingredients":[{"amount":"400","unit":"g","name":"皮と骨を除いて角切りにした白身魚"},{"amount":"300","unit":"g","name":"殻と背わたを除いた生えび"},{"amount":"250","unit":"g","name":"下処理したいかの輪切りと足"},{"amount":"400","unit":"ml","name":"無糖ココナッツミルク"},{"amount":"300","unit":"ml","name":"水"},{"amount":"120","unit":"g","name":"刻んだ白玉ねぎ"},{"amount":"100","unit":"g","name":"刻んだ赤パプリカ"},{"amount":"200","unit":"g","name":"刻んだ完熟トマト"},{"amount":"9","unit":"g","name":"刻んだにんにく"},{"amount":"15","unit":"g","name":"オリーブオイル"},{"amount":"4","unit":"g","name":"塩"},{"amount":"5","unit":"g","name":"刻んだ香菜（お好みで）"}],"steps":[{"title":"野菜を刻む","content":"玉ねぎ、パプリカ、にんにく、トマトを細かく刻みます。","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"野菜を刻む"},{"title":"香味野菜を炒める","content":"鍋に油を入れ、玉ねぎ、パプリカ、にんにくを中火で5分炒めます。","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"香味野菜を炒める"},{"title":"トマトを煮る","content":"トマトを加え、柔らかくなるまで6分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"トマトを煮る"},{"title":"スープを作る","content":"水、ココナッツミルク、塩を加え、弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"スープを作る"},{"title":"いかを煮る","content":"いかを加えて静かに15分煮ます。まだ硬ければ、魚を加える前に柔らかくなるまで煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"いかを煮る"},{"title":"魚を加える","content":"角切りの魚を加え、弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"魚を加える"},{"title":"えびを煮る","content":"えびを加えて3〜4分、ピンク色で不透明になるまで煮ます。魚の火通りといかの柔らかさも確認します。","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"えびを煮る"},{"title":"盛り付ける","content":"熱いうちに盛り、お好みで香菜を添えます。白いご飯やパタコンも合います。","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"盛り付ける"}],"seo":{"title":"コロンビア風シーフードのココナッツ煮込み","description":"コロンビアのカリブ海沿岸風に、白身魚、えび、いかをココナッツとトマトのスープで煮込みます。","image_alt":"コロンビア風シーフードのココナッツ煮込み","faq":[{"q":"冷凍の魚介は使えますか？","a":"はい。冷蔵庫で解凍し、下処理後に量ってください。"},{"q":"いかが硬いのはなぜですか？","a":"静かに煮て、硬ければ数分追加してください。"},{"q":"ソフリットは作り置きできますか？","a":"はい。密閉して冷蔵し、スープと魚介を加える前に温めます。"}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"全量の4分の1（付け合わせを除く）","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"香菜と付け合わせを除いた推定値です。製品により変わります。"},"notes":"<p>魚介は冷蔵庫で解凍し、強く沸騰させないでください。魚は中心温度63 °Cまで加熱し、えびといかは不透明で締まるまで火を通します。魚、甲殻類、軟体類を含みます。</p>","category":"主菜","cuisine":"コロンビア料理","difficulty":"簡単","course":"主菜","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["コロンビア風シーフードのココナッツ煮込み"],"content_html":""},{"language":"pt","slug":"caldeirada-colombiana-de-frutos-do-mar-com-coco","public_path":"/pt/caldeirada-colombiana-de-frutos-do-mar-com-coco","title":"Caldeirada colombiana de frutos do mar com leite de coco","excerpt":"Uma caldeirada da costa caribenha colombiana com peixe, camarão e lula em caldo de coco e refogado de tomate.","summary":"Uma caldeirada da costa caribenha colombiana com peixe, camarão e lula em caldo de coco e refogado de tomate.","ingredients":[{"amount":"400","unit":"g","name":"filé de peixe branco firme, sem pele e espinhas, em cubos"},{"amount":"300","unit":"g","name":"camarões crus limpos e descascados"},{"amount":"250","unit":"g","name":"lula limpa em anéis e tentáculos"},{"amount":"400","unit":"ml","name":"leite de coco sem açúcar"},{"amount":"300","unit":"ml","name":"água"},{"amount":"120","unit":"g","name":"cebola branca picada"},{"amount":"100","unit":"g","name":"pimentão vermelho picado"},{"amount":"200","unit":"g","name":"tomate maduro picado"},{"amount":"9","unit":"g","name":"alho picado"},{"amount":"15","unit":"g","name":"azeite de oliva"},{"amount":"4","unit":"g","name":"sal"},{"amount":"5","unit":"g","name":"coentro fresco picado, opcional"}],"steps":[{"title":"Pique os vegetais","content":"Pique finamente a cebola, o pimentão, o alho e os tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pique os vegetais"},{"title":"Refogue os aromáticos","content":"Cozinhe a cebola, o pimentão e o alho no azeite em fogo médio por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Refogue os aromáticos"},{"title":"Cozinhe o tomate","content":"Adicione o tomate e cozinhe por 6 minutos, até amolecer.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cozinhe o tomate"},{"title":"Prepare o caldo","content":"Adicione a água, o leite de coco e o sal; cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepare o caldo"},{"title":"Cozinhe a lula","content":"Junte a lula e cozinhe em fervura suave por 15 minutos; se ainda estiver firme, cozinhe até amaciar antes de adicionar o peixe.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cozinhe a lula"},{"title":"Adicione o peixe","content":"Junte os cubos de peixe e cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Adicione o peixe"},{"title":"Cozinhe o camarão","content":"Adicione os camarões e cozinhe por 3–4 minutos, até ficarem rosados e opacos. Confira o peixe e a maciez da lula.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cozinhe o camarão"},{"title":"Sirva a caldeirada","content":"Sirva quente com coentro opcional. Acompanhe com arroz branco e patacón, se desejar.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirva a caldeirada"}],"seo":{"title":"Caldeirada colombiana de frutos do mar com leite de coco","description":"Uma caldeirada da costa caribenha colombiana com peixe, camarão e lula em caldo de coco e refogado de tomate.","image_alt":"Caldeirada colombiana de frutos do mar com leite de coco","faq":[{"q":"Posso usar frutos do mar congelados?","a":"Sim. Descongele na geladeira e pese depois de limpos."},{"q":"Por que a lula fica dura?","a":"Mantenha a fervura suave e cozinhe mais alguns minutos se ainda estiver firme."},{"q":"Posso adiantar o refogado?","a":"Sim. Guarde fechado na geladeira e aqueça antes de adicionar o caldo e os frutos do mar."}],"image_variants":["/recetas/casuela-de-mariscos/portada-1x1.webp","/recetas/casuela-de-mariscos/portada-4x3.webp","/recetas/casuela-de-mariscos/portada-16x9.webp"]},"nutrition":{"calories":464.3,"protein_g":45.8,"carbs_g":11.7,"fat_g":27.2,"saturated_fat_g":19.9,"sodium_mg":582.3,"estimated":true,"serving_size":"Um quarto da receita, sem acompanhamentos","source":"USDA FoodData Central, SR Legacy","method":"Suma de nutrientes de ingredientes en peso crudo dividida entre 4; 1 ml de leche de coco se aproxima a 1 g.","note":"Estimativa sem coentro opcional nem acompanhamentos. Leite de coco e frutos do mar variam por produto."},"notes":"<p>Descongele os frutos do mar na geladeira. Cozinhe em fogo suave. O centro do peixe deve atingir 63 °C; camarão e lula devem ficar opacos e firmes. Contém peixe, crustáceos e moluscos. Acompanhamentos não entram na estimativa.</p>","category":"Pratos principais","cuisine":"Colombiana","difficulty":"Fácil","course":"Prato principal","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":65,"servings":4,"image_url":"/recetas/casuela-de-mariscos/portada.webp","keywords":["Caldeirada colombiana de frutos do mar com leite de coco"],"content_html":""}]$data$::jsonb; n integer;
BEGIN
 PERFORM 1 FROM public.recipes WHERE recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280' FOR UPDATE;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280') <> 1 OR NOT EXISTS (SELECT 1 FROM public.recipes WHERE id='6c9d337b-6e50-4b4e-a4f6-eb8bacfd6f9a' AND language='es' AND published=false AND public_path='/casuela-de-mariscos' AND updated_at='2026-10-07 01:12:39.564667+00') THEN RAISE EXCEPTION 'Estado inicial cambió'; END IF;
 IF EXISTS (SELECT 1 FROM public.recipes WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x WHERE x->>'language'<>'es')) OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x WHERE x->>'language'<>'es')) THEN RAISE EXCEPTION 'Colisión de URL'; END IF;
 UPDATE public.recipes r SET slug=s.slug, title=s.title, excerpt=s.excerpt, ingredients=s.ingredients, steps=s.steps, category=s.category, prep_time_minutes=s.prep_time_minutes, cook_time_minutes=s.cook_time_minutes, servings=s.servings, image_url=s.image_url, content_html=s.content_html, summary=s.summary, notes=s.notes, difficulty=s.difficulty, course=s.course, cuisine=s.cuisine, total_time_minutes=s.total_time_minutes, keywords=s.keywords, nutrition=s.nutrition, seo=s.seo, public_path=s.public_path, gallery='[]'::jsonb, video_urls='[]'::jsonb, published=true, editorial_status='published' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE r.id='6c9d337b-6e50-4b4e-a4f6-eb8bacfd6f9a' AND s.language='es';
 INSERT INTO public.recipes (recipe_group_id,language,slug, title, excerpt, ingredients, steps, category, prep_time_minutes, cook_time_minutes, servings, image_url, content_html, summary, notes, difficulty, course, cuisine, total_time_minutes, keywords, nutrition, seo, public_path,published,editorial_status) SELECT '8e31b609-3fb4-4819-9249-760e0fb73280'::uuid,s.language,s.slug, s.title, s.excerpt, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.servings, s.image_url, s.content_html, s.summary, s.notes, s.difficulty, s.course, s.cuisine, s.total_time_minutes, s.keywords, s.nutrition, s.seo, s.public_path,true,'published' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 DELETE FROM public.content_redirects WHERE source_path='/casuela-de-mariscos' AND status_code IN (302,307);
 SELECT count(DISTINCT language) INTO n FROM public.recipes WHERE recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280' AND published=true AND nutrition IS NOT NULL;
 IF n<>7 OR EXISTS(SELECT 1 FROM public.content_redirects WHERE source_path='/casuela-de-mariscos' AND status_code IN (302,307)) THEN RAISE EXCEPTION 'Publicación incompleta'; END IF;
END $block$;
COMMIT;
